-- LOOT1A V2 (2026-11-26, Claude): drops, money and starter equipment for the Exile's Reach creatures. Replaces LOOT1A V1 (works with or without it).
-- Quest drops are not touched. Safe to run twice. Rerunning BEACH1A / BEACH1B removes these rows for those creatures: run this file again.
SET NAMES utf8mb4;
SELECT COUNT(*) AS creatures_found_24 FROM `creature_template` WHERE `entry` IN (150228, 150229, 150238, 151091, 152843, 153239, 153266, 153581, 153582, 153583, 153964, 156814, 156900, 157300, 160394, 160433, 161130, 161131, 161133, 162817, 165150, 9159801, 9159802, 9159803);
